def-hyp(
    __list__(Type.annotation(@$\mathcal{B}$, Set(Set(T@Set.ctxt.T))), Set.subset($\mathcal{B}$, Set.powerset(S@Topology.ctxt.S))),
    Topology.generatedTopology($\mathcal{B}$),
    Set.sep-typed(
        @U,
        Set(T@Set.ctxt.T),
        Logic.forall-typed(
            @x,
            T@Set.ctxt.T,
            Logic.implies(
                Set.mem(x, U),
                Logic.exists-typed(
                    @B_2,
                    Set(T@Set.ctxt.T),
                    Logic.and(Set.mem(B_2, $\mathcal{B}$), Logic.and(Set.mem(x, B_2), Set.subset(B_2, U)))
                )
            )
        )
    )
)
